import { isIP } from "node:net";
import { hash } from "./hash";
import type { Check, Json, Observation, Requirement, Scenario, TurnObservation } from "./contracts";

function record(value: Json | undefined): Record<string, Json> {
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}
function list(value: Json | undefined): Json[] { return Array.isArray(value) ? value : []; }
function promptContainsIntent(prompt: string, intent: TurnObservation["finalPreferences"]): boolean {
  return prompt.split("\n").some((line) => {
    const start = line.indexOf("{");
    if (start < 0) return false;
    try { return hash(JSON.parse(line.slice(start))) === hash(intent); } catch { return false; }
  });
}
function exact(value: Json | undefined): boolean {
  const item = record(value);
  return item.status === "supported" && item.scope === "exact-variant";
}
export function safeSourceUrl(value: string): boolean {
  try {
    const url = new URL(value);
    const authority = value.match(/^https:\/\/([^/?#]+)/i)?.[1] ?? "";
    const host = url.hostname.toLowerCase().replace(/\.$/, "");
    const labels = host.split(".");
    const specialUse = ["localhost", "local", "internal", "localdomain", "home", "lan", "invalid", "test", "example", "onion", "arpa", "alt"];
    return authority.length > 0 && !/[\u0000-\u0020\u007f]/.test(value) && !value.includes("\\") && url.protocol === "https:" && !authority.includes("@") && !authority.includes(":") && !url.username && !url.password && !url.port && !isIP(host) && host.length <= 253 && labels.length >= 2 && labels.every((label) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label)) && !specialUse.some((ending) => host === ending || host.endsWith(`.${ending}`));
  } catch { return false; }
}
export function literalMoney(quote: string, currency: string, amount: number): boolean {
  for (const match of quote.matchAll(/\b(SGD|USD|S\$|US\$)\s*((?:[0-9]{1,3}(?:,[0-9]{3})+|[0-9]+)(?:\.[0-9]{1,2})?)(?![\d,]|\.\d)/gi)) {
    const observedCurrency = /^(?:SGD|S\$)$/i.test(match[1]!) ? "SGD" : "USD";
    if (observedCurrency === currency && Number(match[2]!.replace(/,/g, "")) === amount) return true;
  }
  return false;
}
function normalize(value: string): string { return value.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim(); }
function checkRequirement(requirement: Requirement, turn: TurnObservation, observation: Observation): { ok?: boolean; expected: Json; observed: Json; status?: "blocked" | "unsupported" } {
  const prefs = turn.finalPreferences;
  switch (requirement.kind) {
    case "description": return { ok: requirement.includes.every((word) => normalize(prefs.productDescription).includes(normalize(word))), expected: requirement.includes, observed: prefs.productDescription };
    case "budget": return { ok: prefs.budget?.amount === requirement.maximum && prefs.budget?.currency === requirement.currency && prefs.budget?.minimum === requirement.minimum, expected: { amount: requirement.maximum, currency: requirement.currency, ...(requirement.minimum === undefined ? {} : { minimum: requirement.minimum }) }, observed: prefs.budget ?? null };
    case "budget-null": return { ok: prefs.budget === null, expected: null, observed: prefs.budget ?? null };
    case "preserve": {
      const previous = observation.turns[requirement.from]?.finalPreferences;
      const fields = requirement.fields;
      return { ok: Boolean(previous) && fields.every((field) => hash(prefs[field]) === hash(previous![field])), expected: previous ? Object.fromEntries(fields.map((field) => [field, previous[field]])) as Json : null, observed: Object.fromEntries(fields.map((field) => [field, prefs[field]])) as Json };
    }
    case "criterion": return { ok: prefs.criteria.some((criterion) => criterion.strength === requirement.strength && normalize(criterion.wording).includes(normalize(requirement.includes)) && (requirement.meaning !== "exclude" || /\b(?:no|exclude|avoid|without|excluding)\b/i.test(criterion.wording) && !/\b(?:not|don.t)\s+(?:exclude|avoid)/i.test(criterion.wording)) && (requirement.meaning !== "only" || /\bonly\b/i.test(criterion.wording) && !/\bnot\s+only\b/i.test(criterion.wording))), expected: { wordingIncludes: requirement.includes, strength: requirement.strength, meaning: requirement.meaning ?? "literal-phrase-only" }, observed: prefs.criteria as Json };
    case "response": return { ok: requirement.kinds.includes(String(turn.response?.kind)) && (!requirement.reasons || requirement.reasons.includes(String(turn.response?.reason ?? turn.response?.question))), expected: { kinds: requirement.kinds, ...(requirement.reasons ? { reasons: requirement.reasons } : {}) }, observed: { kind: turn.response?.kind ?? null, reason: turn.response?.reason ?? turn.response?.question ?? null } };
    case "calls": return { ok: turn.providerCalls >= requirement.minimum && turn.providerCalls <= requirement.maximum, expected: { minimum: requirement.minimum, maximum: requirement.maximum }, observed: turn.providerCalls };
    case "clarifications": {
      const count = observation.turns.slice(0, turn.index + 1).filter((item) => ["question", "clarification"].includes(String(item.response?.kind))).length;
      return { ok: count <= requirement.maximum, expected: requirement.maximum, observed: count };
    }
    case "response-length": return { ok: prefs.responseLength === requirement.value, expected: requirement.value, observed: prefs.responseLength };
    case "region": return { ok: prefs.region === requirement.value, expected: requirement.value, observed: prefs.region };
    case "pending": return { ok: Boolean(prefs.pendingChange) === requirement.value, expected: requirement.value, observed: prefs.pendingChange as Json };
    case "no-choice": return { ok: !record(turn.response?.research).choice, expected: null, observed: record(turn.response?.research).choice ?? null };
    case "products": { const products = list(record(turn.response?.research).products); return { ok: products.length >= requirement.minimum, expected: requirement.minimum, observed: products.length }; }
    case "cancelled": return { ok: turn.cancelled && observation.events.some((event) => event.turn === turn.index && event.kind === "provider-aborted"), expected: "Cancellation reaches the actual local SDK request", observed: { cancelled: turn.cancelled, providerAbort: observation.events.some((event) => event.turn === turn.index && event.kind === "provider-aborted") } };
    case "unassessed": return { status: requirement.capability.startsWith("unsupported:") ? "unsupported" : "blocked", expected: requirement.capability, observed: requirement.reason };
  }
}
function evidence(observation: Observation, turn: number): number[] { return observation.events.filter((event) => event.turn === turn).map((event) => event.sequence); }
function assessmentFields(product: Record<string, Json>): Map<string, Record<string, Json>> {
  return new Map([
    ["identity", record(product.identity)], ["requestMatch", record(product.requestMatch)],
    ...list(product.criteria).map((item): [string, Record<string, Json>] => [`criterion:${record(item).criterionId}`, record(record(item).assessment)]),
    ...list(product.attributes).map((item): [string, Record<string, Json>] => [`attribute:${record(item).name}`, record(record(item).assessment)]),
    ["price", record(record(product.price).assessment)], ["budget", record(product.budget)],
  ]);
}
function hardCriterionRetention(scenario: Scenario, observation: Observation): Check[] {
  let retained = observation.initialPreferences.criteria.filter((criterion) => criterion.strength === "hard");
  const checks: Check[] = [];
  for (const turn of observation.turns) {
    const changes = scenario.criterionChanges?.filter((change) => change.after === turn.index) ?? [];
    retained = turn.action.kind === "reset" ? [] : retained.filter((prior) => !changes.some((change) => normalize(prior.wording).includes(normalize(change.priorWordingIncludes))));
    checks.push({ id: `hard-criterion-retention:${turn.index}`, turn: turn.index, critical: true,
      status: retained.every((prior) => turn.finalPreferences.criteria.some((current) => current.strength === "hard" && normalize(current.wording) === normalize(prior.wording))) ? "pass" : "fail",
      expected: structuredClone(retained) as Json, observed: turn.finalPreferences.criteria as Json, evidence: evidence(observation, turn.index) });
    for (const criterion of turn.finalPreferences.criteria.filter((item) => item.strength === "hard")) {
      if (!retained.some((prior) => normalize(prior.wording) === normalize(criterion.wording))) retained.push(criterion);
    }
  }
  return checks;
}
function checksForResearch(observation: Observation, turn: TurnObservation): Check[] {
  const snapshot = record(turn.response?.research);
  if (!Object.keys(snapshot).length) return [];
  const result: Check[] = [];
  const emit = (id: string, ok: boolean, expected: Json, observed: Json) => result.push({ id, turn: turn.index, status: ok ? "pass" : "fail", critical: true, expected, observed, evidence: evidence(observation, turn.index) });
  const upstream = record(observation.material.body);
  const upstreamProducts = list(record(upstream.answer).products).map(record);
  const upstreamSources = list(upstream.citations).map(record);
  const sources = list(snapshot.sources).map(record);
  const sourceMap = new Map(sources.map((source) => [String(source.id), source]));
  emit("safe-source-urls", sources.every((source) => typeof source.url === "string" && safeSourceUrl(source.url)), "Safe public HTTPS URLs", sources.map((source) => source.url ?? null));
  emit("source-provenance", sources.every((source) => upstreamSources.some((item) => item.url === source.url && typeof item.text === "string" && typeof source.text === "string" && item.text.includes(source.text))), "Every source URL and retained text comes from the supplied material", sources.map((source) => ({ url: source.url ?? null, text: source.text ?? null })));
  const products = list(snapshot.products).map(record);
  emit("fabricated-products", products.every((product) => upstreamProducts.some((item) => item.id === product.id && item.name === product.name && item.variant === product.variant)), "Every published identity originates in the fixed provider input", products.map((product) => ({ id: product.id ?? null, name: product.name ?? null, variant: product.variant ?? null })));
  for (const product of products) {
    const upstreamProduct = upstreamProducts.find((item) => item.id === product.id);
    if (upstreamProduct) {
      const published = assessmentFields(product);
      for (const [field, prior] of assessmentFields(upstreamProduct)) {
        if (!["contradicted", "conflict"].includes(String(prior.status))) continue;
        const passages = list(prior.support).map(record).filter((span) => typeof span.url === "string" && typeof span.quote === "string" && upstreamSources.some((source) => source.url === span.url && typeof source.text === "string" && source.text.includes(String(span.quote))));
        const current = published.get(field) ?? {};
        const preserved = passages.length > 0 && (current.status === prior.status || prior.status === "contradicted" && current.status === "conflict") && passages.every((span) => list(current.support).map(record).some((support) => support.quote === span.quote && sourceMap.get(String(support.sourceId))?.url === span.url && String(sourceMap.get(String(support.sourceId))?.text ?? "").includes(String(span.quote))));
        const blocksChoice = field === "identity" || field === "requestMatch" || field.startsWith("criterion:") && turn.finalPreferences.criteria.some((criterion) => criterion.strength === "hard" && field === `criterion:${criterion.id}`) || (field === "price" || field === "budget") && turn.finalPreferences.budget !== null;
        emit(`adverse-evidence:${product.id}:${field}`, preserved && (!blocksChoice || record(snapshot.choice).productId !== product.id), "Source-linked adverse status and complete passages survive publication. Adverse identity, request or applicable hard fit prevents recommendation", { supplied: prior, published: current, blocksChoice, chosen: record(snapshot.choice).productId === product.id });
      }
    }
    const assessments = [product.identity, product.requestMatch, ...list(product.criteria).map((item) => record(item).assessment), ...list(product.attributes).map((item) => record(item).assessment), ...(product.price ? [record(product.price).assessment] : []), ...(product.budget ? [product.budget] : [])];
    const support = assessments.flatMap((item) => list(record(item).support).map(record));
    emit(`quote-containment:${product.id}`, support.every((span) => {
      const source = sourceMap.get(String(span.sourceId));
      return source && typeof source.text === "string" && typeof span.start === "number" && typeof span.end === "number" && source.text.slice(span.start, span.end) === span.quote;
    }), "Every quote is an exact contiguous retained passage", support);
    emit(`stock-honesty:${product.id}`, product.stock === "unverified", "unverified", product.stock ?? null);
    const price = record(product.price);
    if (product.price) {
      const supplied = record(upstreamProduct?.price);
      const moneySupported = list(record(price.assessment).support).map(record).some((span) => {
        if (typeof span.quote !== "string" || typeof price.amount !== "number") return false;
        return literalMoney(span.quote, String(price.currency), price.amount);
      });
      emit(`price-attribution:${product.id}`, price.amount === supplied.amount && price.currency === supplied.currency && price.variant === supplied.variant && moneySupported, "Amount, explicit currency and variant match literal provider evidence", price);
      const upstreamText = list(record(supplied.assessment).support).map((span) => String(record(span).quote ?? "")).join("\n");
      emit(`price-conditions:${product.id}`, !(price.conditionsResolved === true && (supplied.conditionsResolved === false || /members? only|voucher|subscription|per month|\/month/i.test(upstreamText))), "Unresolved membership, voucher and recurring terms cannot become unconditional", { conditions: price.conditions ?? null, conditionsResolved: price.conditionsResolved ?? null });
    }
  }
  if (snapshot.choice) {
    const chosen = products.find((product) => product.id === record(snapshot.choice).productId);
    const prefs = turn.finalPreferences;
    const price = record(chosen?.price);
    const criteria = list(chosen?.criteria).map(record);
    const fits = Boolean(chosen && exact(chosen.identity) && exact(chosen.requestMatch) && chosen.variant && prefs.criteria.filter((criterion) => criterion.strength === "hard").every((criterion) => criteria.some((item) => item.criterionId === criterion.id && exact(item.assessment))) && (!prefs.budget || (typeof price.amount === "number" && price.currency === prefs.budget.currency && price.amount <= prefs.budget.amount && price.amount >= (prefs.budget.minimum ?? 0) && price.variant === chosen.variant && price.conditionsResolved === true && exact(price.assessment) && exact(chosen.budget))));
    emit("hard-choice-eligibility", fits, "Every recommendation has exact request/hard fit, applicable currency, variant and both price bounds", snapshot.choice);
  }
  return result;
}
export function grade(scenario: Scenario, observation: Observation): Check[] {
  const checks: Check[] = hardCriterionRetention(scenario, observation);
  for (const milestone of scenario.milestones) {
    const turn = observation.turns[milestone.after];
    if (!turn) {
      checks.push({ id: `missing-turn:${milestone.after}`, turn: milestone.after, status: "blocked", critical: false, expected: "Scenario action completes", observed: observation.applicationError ?? "Earlier action did not complete", evidence: [] });
      continue;
    }
    for (const [index, requirement] of milestone.requirements.entries()) {
      const result = checkRequirement(requirement, turn, observation);
      checks.push({ id: `${requirement.kind}:${milestone.after}:${index}`, turn: milestone.after, status: result.status ?? (result.ok ? "pass" : "fail"), critical: requirement.kind === "criterion" ? requirement.strength === "hard" : requirement.kind === "preserve" ? requirement.fields.some((field) => field === "budget" ? JSON.stringify(turn.finalPreferences.budget) !== JSON.stringify(observation.turns[requirement.from]?.finalPreferences.budget) : field === "criteria" ? observation.turns[requirement.from]?.finalPreferences.criteria.some((prior) => prior.strength === "hard" && !turn.finalPreferences.criteria.some((current) => current.strength === "hard" && current.wording === prior.wording)) : false) : ["budget", "budget-null", "clarifications", "cancelled"].includes(requirement.kind), expected: result.expected, observed: result.observed, evidence: evidence(observation, milestone.after) });
    }
  }
  for (const turn of observation.turns) {
    const events = observation.events.filter((event) => event.turn === turn.index);
    const count = turn.providerCalls;
    checks.push({ id: `bounded-dispatch:${turn.index}`, turn: turn.index, status: count <= 1 ? "pass" : "fail", critical: true, expected: "At most one provider dispatch per explicit user action", observed: count, evidence: evidence(observation, turn.index) });
    const request = events.find((event) => event.kind === "provider-request");
    if (request) {
      const payload = record(record(request.body).body);
      const query = String(payload.query ?? "");
      const prompt = String(payload.systemPrompt ?? "");
      const prefs = turn.finalPreferences;
      const intentIncluded = promptContainsIntent(prompt, prefs);
      const intentRetained = query === prefs.productDescription && intentIncluded;
      const firstResearch = events.find((event) => event.kind === "app-request" && record(event.body).phase === "research");
      checks.push({ id: `research-query-intent:${turn.index}`, turn: turn.index, status: intentRetained ? "pass" : "fail", critical: true, expected: "Actual accepted open objective and complete structured intent reach provider", observed: { query, intentIncluded }, evidence: [request.sequence] });
      checks.push({ id: `research-after-prepare:${turn.index}`, turn: turn.index, status: firstResearch && firstResearch.sequence < request.sequence ? "pass" : "fail", critical: true, expected: "No provider call during prepare", observed: { researchEvent: firstResearch?.sequence ?? null, providerEvent: request.sequence }, evidence: [request.sequence] });
    }
    checks.push(...checksForResearch(observation, turn));
  }
  if (observation.applicationError) checks.push({ id: "application-transport", turn: null, status: "fail", critical: true, expected: "Actual app returns a valid response for supported input", observed: observation.applicationError, evidence: observation.events.map((event) => event.sequence) });
  return checks;
}

export const DATASET_VERSION = "1.0.0";
export const ASSERTION_VERSION = "4.0.0";
export const ADAPTER_VERSION = "normal-v5.2-local-fixed-fallback";
export const categories = ["conversational-understanding", "preference-extraction", "contextual-clarification", "budget-currency", "preference-retention", "corrections-dissatisfaction", "research-selection", "product-relevance", "comparison-quality", "evidence-honesty", "chat-interaction", "recovery-safety"] as const;
export type Category = typeof categories[number];
export type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export type Intent = {
  productDescription: string;
  criteria: { id: string; wording: string; strength: "hard" | "flexible" }[];
  budget: { amount: number; minimum?: number; currency: string } | null;
  budgetClarified: boolean;
  pendingChange: { kind: string; id: string; originalRequest: string; reason: string; message: string; explanation: string; missingSlot?: string; draft?: { amount: number | null; minimum: number | null; currency: string | null } } | null;
  region: string;
  responseLength: string;
  revision: number;
  version: number;
};
export type Action =
  | { kind: "message"; text: string }
  | { kind: "skip-budget" }
  | { kind: "reset" }
  | { kind: "repeat-research" }
  | { kind: "cancel"; text: string };
export type Requirement =
  | { kind: "description"; includes: string[] }
  | { kind: "budget"; maximum: number; minimum?: number; currency: string }
  | { kind: "budget-null" }
  | { kind: "preserve"; from: number; fields: ("budget" | "criteria" | "region" | "productDescription")[] }
  | { kind: "criterion"; includes: string; strength: "hard" | "flexible"; meaning?: "exclude" | "only" }
  | { kind: "response"; kinds: string[]; reasons?: string[] }
  | { kind: "calls"; minimum: number; maximum: number }
  | { kind: "clarifications"; maximum: number }
  | { kind: "response-length"; value: "concise" | "expanded" }
  | { kind: "region"; value: string }
  | { kind: "pending"; value: boolean }
  | { kind: "no-choice" }
  | { kind: "products"; minimum: number }
  | { kind: "cancelled" }
  | { kind: "unassessed"; capability: string; reason: string };
export type Milestone = { after: number; requirements: Requirement[] };
export type CriterionChange = { after: number; priorWordingIncludes: string; reason: string };
export type ScenarioContract = {
  id: string;
  revision: number;
  category: Category;
  title: string;
  actions: Action[];
  provider: string;
  expectedBehavior: string[];
  milestones: Milestone[];
  criterionChanges?: CriterionChange[];
  review: { status: "author-drafted" | "independently-reviewed"; reference: string };
  issue?: number;
};
export type Scenario = ScenarioContract;
export type PublicScenario = Pick<Scenario, "id" | "actions" | "provider">;
export type Material = {
  id: string;
  kind: "synthetic" | "derived-historical-source" | "recorded-exa-response";
  label: string;
  capturedAt: string | null;
  provenance: string[];
  sha256: string;
  body: Json;
  status: number;
  delayMs?: number;
};
export type Event = {
  sequence: number;
  turn: number;
  attemptId?: string;
  kind: "app-request" | "app-response" | "provider-request" | "provider-response" | "admission" | "settlement" | "cancelled" | "provider-aborted" | "reset" | "interpreter-request" | "interpreter-response" | "input-limitation";
  elapsedMs: number;
  body: Json;
};
export type TurnObservation = {
  index: number;
  action: Action;
  initialPreferences: Intent;
  finalPreferences: Intent;
  response: Record<string, Json> | null;
  intentHandling: "local" | "synthetic-fallback" | "unavailable" | "not-prepared";
  providerCalls: number;
  cancelled: boolean;
};
export type Observation = {
  scenarioId: string;
  initialPreferences: Intent;
  finalPreferences: Intent;
  material: Material;
  turns: TurnObservation[];
  events: Event[];
  network: { denied: string[]; allowedOriginCount: number; externalRequests: 0 };
  interpretation: { mode: "fixed-proposals" | "unavailable"; inputHash: string | null; openAIHttpRequests: 0; ollamaHttpRequests: 0; consumedTurns: number[]; unconsumedTurns: number[]; invocations: number; suppliedTurns: Json[]; limitations: string[] };
  cleanup: boolean;
  applicationError: string | null;
};
export type Check = {
  id: string;
  turn: number | null;
  status: "pass" | "fail" | "blocked" | "unsupported";
  critical: boolean;
  expected: Json;
  observed: Json;
  evidence: number[];
};
export type CaseResult = {
  id: string;
  category: Category;
  contract: ScenarioContract;
  material: Material;
  scenarioHash: string;
  expectationHash: string;
  materialHash: string;
  execution: "executed" | "infrastructure-error";
  verdict: "pass" | "fail" | "blocked" | "unsupported";
  expectedBehavior: string[];
  observation: Observation | null;
  checks: Check[];
  semantic: { status: "not-run"; reason: string; scores: null };
  reproduction: string;
  error?: string;
};
export type Metric = { passed: number; assessed: number; unassessed: number; rate: number | null };
export type RunReport = {
  schemaVersion: 4;
  datasetContracts: ScenarioContract[];
  createdAt: string;
  runId: string;
  datasetVersion: string;
  datasetHash: string;
  assertionVersion: string;
  adapterVersion: string;
  implementationInputs: { grading: { path: string; text: string }[]; adapter: { path: string; text: string }[] };
  implementationHashes: { grading: string; adapter: string; suite: string };
  application: { commit: string; tree: string; dirty: boolean; sourceHash: string };
  suite: { commit: string; dirty: boolean };
  configuration: { provider: string; model: null; exaCreditsConsumed: 0; composition: string; interpretation: string; interpretationMode: "fixed-fallback" | "local-only" | "mixed" | "unexecuted"; openAIHttpRequests: 0; ollamaHttpRequests: 0 };
  cases: CaseResult[];
  summary: {
    total: number; executed: number; passed: number; failed: number; blocked: number; unsupported: number; infrastructureErrors: number; criticalFailures: number; criticalScenarios: number; observedTurns: number; observedClarifications: number;
    categories: Record<string, Metric>;
    metrics: Record<string, Metric>;
    acceptance: "pass" | "fail" | "inconclusive";
  };
  limitations: string[];
};

import { createHash } from "node:crypto";
export function hash(value: unknown): string {
  return createHash("sha256").update(typeof value === "string" ? value : JSON.stringify(value, (_key, item: unknown) => item && typeof item === "object" && !Array.isArray(item) ? Object.fromEntries(Object.entries(item).sort(([left], [right]) => left.localeCompare(right))) : item)).digest("hex");
}

export function materialPayloadHash(material: { body: unknown; status: number; delayMs?: number }): string {
  return hash({ body: material.body, status: material.status, delayMs: material.delayMs ?? 0 });
}

import { readFile } from "node:fs/promises";
import { z } from "zod";
import { categories, type Scenario } from "./contracts";
import { criterionChanges, milestones } from "./dataset/milestones";
import { hash } from "./hash";
const RawScenario = z.object({ id: z.string().regex(/^FN-[A-Z]{2}-\d{3}$/), dimension: z.string(), turns: z.array(z.string().min(1)).min(2), hard: z.array(z.string()).min(1), expect: z.array(z.string()).min(1), critical: z.array(z.string()).min(1), provider: z.string() }).strict();
const aliases: Record<string, typeof categories[number]> = {
  "budget-currency-reasoning": "budget-currency", "multi-turn-preference-retention": "preference-retention", "user-corrections-dissatisfaction": "corrections-dissatisfaction", "research-tool-selection": "research-selection", "product-comparison-quality": "comparison-quality", "evidence-attribution-source-honesty": "evidence-honesty", "evidence-attribution-honesty": "evidence-honesty", "chat-presentation-interaction": "chat-interaction", "error-recovery-safety": "recovery-safety",
};
export async function loadDataset() {
  const source = await readFile(new URL("./dataset/scenarios.v1.jsonl", import.meta.url), "utf8");
  const raw = source.trim().split("\n").map((line) => RawScenario.parse(JSON.parse(line)));
  const ids = raw.map((row) => row.id);
